 for(const b of builtins){const i=existing.findIndex(c=>c.id===b.id||c.name===b.name);if(i<0)existing.push(b);else if(b.id==='harlestone'&&(!existing[i].tees||existing[i].tees.length===0))existing[i]=b;}
