async function addPlayer(p){const id=auth?.user?.id||uid();const verifiedEmail=String(auth?.user?.email||'').trim().toLowerCase();const claimed=claimToken?state.players.find(q=>(q.unclaimed||q.placeholder||q.guest)&&q.claimToken===claimToken&&(!q.email||String(q.email).trim().toLowerCase()===verifiedEmail)):null;const x={...p,id,email:verifiedEmail||null,emailVerified:!!verifiedEmail,authUserId:auth?.user?.id||null,passkeyEnabled:false,placeholder:false,guest:false,unclaimed:false,claimToken:null,membershipStatus:'member',claimedAt:claimed?new Date().toISOString():null};if(CLOUD&&auth?.access_token&&auth?.user?.id){try{await saveProfile(auth.access_token,{id,display_name:p.name,handicap_index:+p.hi||0,passkey_enabled:false})}catch(e){alert('Your cloud profile could not be saved. Please try again.');return}}setState(s=>{const oldId=claimed?.id;const normEmail=e=>String(e||'').trim().toLowerCase();const linkedIds=[...new Set([...(oldId?[oldId]:[]),...(verifiedEmail?s.players.filter(q=>(q.unclaimed||q.placeholder||q.guest)&&normEmail(q.email)===verifiedEmail).map(q=>q.id):[])])];const swap=a=>(a||[]).map(v=>linkedIds.includes(v)?id:v);const players=[...s.players.filter(q=>!linkedIds.includes(q.id)&&q.authUserId!==id&&q.id!==id),x];if(!linkedIds.length)return {...s,players,societies:s.societies.map(q=>q.id===society?.id?{...q,members:[...new Set([...(q.members||[]),id])]}:q)};const societies=s.societies.map(q=>({...q,members:[...new Set(swap(q.members))],admins:[...new Set(swap(q.admins))],ownerId:q.ownerId===oldId?id:q.ownerId}));const leagues=(s.leagues||[]).map(g=>{const snap={...(g.startingHandicaps||{})};for(const old of linkedIds)if(Object.prototype.hasOwnProperty.call(snap,old)){if(!Object.prototype.hasOwnProperty.call(snap,id))snap[id]=snap[old];delete snap[old]}return {...g,memberIds:[...new Set(swap(g.memberIds))],teams:(g.teams||[]).map(t=>({...t,memberIds:[...new Set(swap(t.memberIds))]})),startingHandicaps:snap}});const comps=(s.comps||[]).map(q=>({...q,entries:[...new Set(swap(q.entries))],invites:[...new Set(swap(q.invites))],pairs:(q.pairs||[]).map(pr=>({...pr,ids:swap(pr.ids)})),roundGroups:(q.roundGroups||[]).map(rg=>({...rg,playerIds:swap(rg.playerIds),ids:swap(rg.ids)}))}));const cards=(s.cards||[]).map(card=>linkedIds.includes(card.playerId)?{...card,playerId:id}:card);const contacts=Object.fromEntries(Object.entries(s.contacts||{}).filter(([k])=>!linkedIds.includes(k)).map(([k,v])=>[k,[...new Set(swap(v))]]));const hiddenContacts=Object.fromEntries(Object.entries(s.hiddenContacts||{}).filter(([k])=>!linkedIds.includes(k)).map(([k,v])=>[k,[...new Set(swap(v))]]));return {...s,players,societies,leagues,comps,cards,contacts,hiddenContacts}});setMe(id);localStorage.setItem('ggc-me',id);if(claimed)history.replaceState({},'',location.pathname);setModal(null)}
