 function hcap(id){const p=state.players.find(x=>x.id===id);const old=cardFor(id);return {hi:old?.handicapIndexUsed??p?.hi??0,ch:old?.courseHandicap??courseHandicap(p?.hi,tee,par),ph:old?.playingHandicap??playingHandicap(p?.hi,tee,par,allowance)}}
 function normalShots(ph,si){const base=Math.trunc(ph/18),rem=Math.abs(ph%18);return ph>=0?base+(si<=rem?1:0):base-(rem>0&&si>18-rem?1:0)}
